/bin/bash -lc 'verify_tmp=$(find "$TMPDIR" -maxdepth 1 -type d -name '"'mcbu-verify.*' | sort | tail -1)
curl --insecure --fail --location --silent --show-error --connect-timeout 20 --max-time 60 -A 'Mozilla/5.0 (compatible; institution-verification/1.0)' 'https://mcbu.ac.in/' -o \""'$verify_tmp/mcbu_home.html"
printf '"'%s\\n' '-- homepage status --'
wc -c \""'$verify_tmp/mcbu_home.html"
rg -io '"'<title["'^>]*>[''^<]*|<h[1-3][''^>]*>[''^<]*|Chhatarpur|Chhatrasal|Bundelkhand|course|admission|programme|program'"' \""'$verify_tmp/mcbu_home.html" | head -120
printf '"'%s\\n' '-- links --'
python3 - \""'$verify_tmp/mcbu_home.html" <<'"'PY'
from html.parser import HTMLParser
import sys
class P(HTMLParser):
    def __init__(self): super().__init__(); self.a=None; self.buf=[]
    def handle_starttag(self,t,a):
        if t=='a': self.a=dict(a); self.buf=[]
    def handle_data(self,d):
        if self.a is not None: self.buf.append(' '.join(d.split()))
    def handle_endtag(self,t):
        if t=='a' and self.a is not None:
            text=' '.join(x for x in self.buf if x).strip()
            href=self.a.get('href','')
            if text or href: print(text+'\\t'+href)
            self.a=None; self.buf=[]
P().feed(open(sys.argv[1], encoding='utf-8', errors='replace').read())
PY"

