import sys
try:
    from bs4 import BeautifulSoup
except Exception as e:
    print('NO_BS4', e); raise SystemExit(0)
for path in sys.argv[1:]:
    print('\\n###', path.rsplit('/',1)[-1])
    soup=BeautifulSoup(open(path,encoding='utf-8',errors='replace'),'html.parser')
    print('TITLE:', soup.title.get_text(' ',strip=True) if soup.title else '')
    for tag in soup.find_all(['table','h1','h2','h3','h4','p','li']):
        txt=' '.join(tag.get_text(' ',strip=True).split())
        if txt and any(k in txt.lower() for k in ['programme','program','course','duration','eligib','chhatarpur','guraiya','panna','address','university','admission']):
            print(tag.name, repr(txt[:500]))
PY"

